function layoutMetaSummary(meta: LayoutMetaV1): Layout & { summaryOnly: true } {
  const layout = JSON.parse(meta.layoutShell) as Layout;
  const refuse = (): never => {
    throw new Error('the fragments of a worker layout summary live in the worker');
  };
  for (const page of layout.pages) {
    Object.defineProperty(page, 'fragments', { get: refuse, enumerable: true, configurable: true });
  }
  return Object.assign(layout, { summaryOnly: true as const });
}

function paginaMetPositie(paginas: readonly IndelingPagina[], positie: number | null) {
  if (positie === null) return -1;
  return paginas.findIndex((p) =>
    p.fragments.some((f) => f.pmStart !== undefined && f.pmEnd !== undefined && f.pmStart <= positie && positie <= f.pmEnd),
  );
}

function tekstbreedteOpPagina(paginas: readonly IndelingPagina[], positie: number | null | undefined): number | null {
  if (positie === null || positie === undefined) return null;
  for (const p of paginas) {
    if (!p.size || !p.margins) continue;
    if (p.fragments.some((f) => f.pmStart !== undefined && f.pmEnd !== undefined && f.pmStart <= positie && positie <= f.pmEnd))
      return Math.round((p.size.w - p.margins.left - p.margins.right) * TWIPS_PER_PX);
  }
  return null;
}

function paginaSelectie<T, R extends Rand>(
  paginas: readonly T[],
  meet: (pagina: T) => R,
  boven: number,
  onder: number,
  gestapeld = false,
): { pagina: T; rect: R; index: number }[] {
  const cache = new Map<number, R>();
  const rect = (i: number) => {
    let r = cache.get(i);
    if (!r) {
      r = meet(paginas[i]);
      cache.set(i, r);
    }
    return r;
  };
  const verzamel = (van: number, tot: number) => {
    const uit = [];
    for (let i = van; i < tot; i++) {
      const r = rect(i);
      if (!(r.bottom < boven || r.top > onder))
        uit.push({ pagina: paginas[i], rect: r, index: i });
    }
    return uit;
  };
  if (
    !gestapeld ||
    paginas.length < 16 ||
    !Number.isFinite(boven) ||
    !Number.isFinite(onder) ||
    boven > onder
  )
    return verzamel(0, paginas.length);
  let van = 0,
    tot = paginas.length;
  while (van < tot) {
    const midden = van + Math.floor((tot - van) / 2),
      r = rect(midden);
    if (
      !Number.isFinite(r.top) ||
      !Number.isFinite(r.bottom) ||
      r.bottom < r.top
    )
      return verzamel(0, paginas.length);
    if (r.bottom < boven) van = midden + 1;
    else tot = midden;
  }
  const eerste = van;
  tot = paginas.length;
  while (van < tot) {
    const midden = van + Math.floor((tot - van) / 2),
      r = rect(midden);
    if (
      !Number.isFinite(r.top) ||
      !Number.isFinite(r.bottom) ||
      r.bottom < r.top
    )
      return verzamel(0, paginas.length);
    if (r.top <= onder) van = midden + 1;
    else tot = midden;
  }
  return verzamel(eerste, van);
}
function zichtbarePaginaElementen(
  paginas: readonly HTMLElement[],
  venster: Rand,
  marge: number,
) {
  const kolom = paginas[0]?.parentElement;
  const stijl = kolom?.classList.contains("canvas-pages__column")
    ? getComputedStyle(kolom)
    : null;
  // Alleen de eigen paginakolom heeft deze vaste verticale indeling.
  const gestapeld =
    stijl?.display === "flex" &&
    stijl.flexDirection === "column" &&
    paginas.every((p) => p.parentElement === kolom);
  return paginaSelectie(
    paginas,
    (p) => p.getBoundingClientRect(),
    venster.top - marge,
    venster.bottom + marge,
    gestapeld,
  );
}

function zichtbaarBereik(
  pagina: readonly { boven: number; onder: number; van: number; tot: number }[],
  venster: { boven: number; onder: number },
): [number, number] | null {
  let van = Infinity;
  let tot = -Infinity;
  for (const p of pagina) {
    if (p.onder < venster.boven - MARGE || p.boven > venster.onder + MARGE) continue;
    van = Math.min(van, p.van);
    tot = Math.max(tot, p.tot);
  }
  return van <= tot ? [van, tot] : null;
}
function bereikInBeeld(sessie: SpellingSessie, laag: HTMLElement | null): [number, number] | null | undefined {
  const vlak = laag?.closest<HTMLElement>(SCROLLVLAK);
  if (!vlak) return null;
  // Het zichtbare deel: het scrollvlak, begrensd door het venster.
  const v = vlak.getBoundingClientRect();
  // Een verborgen tabblad houdt zijn spellingsgegevens, maar hoeft geen
  // pagina's of woordgeometrie voor een onzichtbare laag uit te lezen.
  if (v.width <= 0 || v.bottom <= v.top || v.bottom <= 0 || v.top >= window.innerHeight) return undefined;
  const zichtbaarheid = getComputedStyle(vlak).visibility;
  if (zichtbaarheid === "hidden" || zichtbaarheid === "collapse") return undefined;
  const indeling = sessie.editor()?.getEditorRef()?.getLayout();
  if (!indeling) return null;
  const venster = { boven: Math.max(v.top, 0), onder: Math.min(v.bottom, window.innerHeight) };
  const elementen = vlak.querySelectorAll<HTMLElement>(".canvas-page");
  if (elementen.length !== indeling.pages.length) return null;
  const paginas = zichtbarePaginaElementen([...elementen], { top: venster.boven, bottom: venster.onder }, MARGE).map(({ index, rect: r }) => {
    const p = indeling.pages[index];
    let van = Infinity;
    let tot = -Infinity;
    for (const f of p.fragments as { pmStart?: number; pmEnd?: number }[]) {
      if (typeof f.pmStart === "number") van = Math.min(van, f.pmStart);
      if (typeof f.pmEnd === "number") tot = Math.max(tot, f.pmEnd);
    }
    return { boven: r.top, onder: r.bottom, van, tot };
  });
  return zichtbaarBereik(paginas, venster);
}

function paginas(ref: DocxEditorRef) {
  return (engine(ref).weergave.getLayout()?.pages ?? []) as unknown as { number?: number; sectionIndex?: number; fragments: Fragment[] }[];
}
function naarPositie(ref: DocxEditorRef, positie: number | null | undefined) {
  if (positie === null || positie === undefined) return false;
  const { weergave } = engine(ref);
  weergave.setSelection(positie);
  weergave.scrollToPosition(positie);
  ref.focus();
  return true;
}
function gaNaarPagina(ref: DocxEditorRef, nummer: number) {
  const lijst = paginas(ref);
  if (!Number.isInteger(nummer) || nummer < 1 || nummer > lijst.length) return;
  const eerste = (fragmenten: Fragment[]) => {
    for (const f of fragmenten) {
      const positie = f.kind === "paragraph"
        ? f.resolvedLines?.[0]?.segments?.find((s) => typeof s.run?.pmStart === "number")?.run?.pmStart ?? f.pmStart
        : f.pmStart;
      if (positie !== undefined) return positie;
    }
    return undefined;
  };
  let positie = eerste(lijst[nummer - 1].fragments);
  // Een lege tussenpagina kan door een sectie-einde ontstaan. Kies dan de
  // eerstvolgende invoegpositie, of het einde van de voorgaande hoofdtekst.
  if (positie === undefined) {
    for (let i = nummer; i < lijst.length && positie === undefined; i++)
      positie = eerste(lijst[i].fragments);
    for (let i = nummer - 2; i >= 0 && positie === undefined; i--)
      positie = [...lijst[i].fragments].reverse().find((f) => f.pmEnd !== undefined)?.pmEnd;
  }
  if (positie !== undefined) {
    engine(ref).weergave.setSelection(positie);
    ref.focus();
  }
  ref.scrollToPage(nummer);
}
function regelDoelen(ref: DocxEditorRef): Doel[] {
  const uit: Doel[] = [];
  for (const p of paginas(ref))
    for (const f of p.fragments) {
      if (f.kind !== "paragraph") continue;
      const regels = f.resolvedLines ?? [];
      const aantal = Math.max(regels.length, (f.toLine ?? 0) - (f.fromLine ?? 0));
      for (let i = 0; i < aantal; i++) {
        const positie = regels[i]?.segments?.find((s) => typeof s.run?.pmStart === "number")?.run?.pmStart ?? f.pmStart;
        uit.push({ nr: uit.length + 1, label: i18next.t("writer:find.goTo.labels.line", { n: uit.length + 1 }), ga: (r) => void naarPositie(r, positie) });
      }
    }
  return uit;
}
